# frozen_string_literal: true

RSpec.describe 'RuboCop::CLI --prune-todo', :isolated_environment do # rubocop:disable RSpec/DescribeClass
  subject(:cli) { RuboCop::CLI.new }

  include_context 'cli spec behavior'

  let(:header) do
    <<~YAML
      # This configuration was generated by
      # `rubocop --auto-gen-config`
      # on 2026-10-05 12:00:00 UTC using RuboCop version 1.86.0.
      # The point is for the user to remove these configuration records
      # one by one as the offenses are removed from the code base.
      # Note that changes in the inspected code, or installation of new
      # versions of RuboCop, may require this file to be generated again.
    YAML
  end

  before do
    create_file('.rubocop.yml', <<~YAML)
      inherit_from: .rubocop_todo.yml
    YAML
    create_file('clean.rb', <<~RUBY)
      # frozen_string_literal: true

      x = 1
      puts x
    RUBY
    create_file('offending.rb', <<~RUBY)
      # frozen_string_literal: true

      @@bad = 1
      @@worse = 2
      puts @@bad, @@worse
    RUBY
  end

  def todo
    File.read('.rubocop_todo.yml')
  end

  context 'when the todo file has stale and live entries' do
    before do
      create_file('.rubocop_todo.yml', <<~YAML)
        #{header}
        # Offense count: 3
        Style/ClassVars:
          Exclude:
            - 'clean.rb'
            - 'deleted.rb'
            - 'offending.rb'

        # Offense count: 1
        # This cop supports safe autocorrection (--autocorrect).
        Style/StringLiterals:
          Exclude:
            - 'clean.rb'

        # Offense count: 1
        Lint/UselessAssignment:
          Exclude:
            - 'offending.rb'
      YAML
    end

    it 'removes the stale entries and keeps everything else' do
      expect(cli.run(['--prune-todo'])).to eq(0)
      expect($stdout.string).to eq(<<~OUTPUT)
        Removed 4 unused todo entries from `.rubocop_todo.yml`:
          Style/ClassVars: clean.rb
          Style/ClassVars: deleted.rb
          Style/StringLiterals: clean.rb
          Lint/UselessAssignment: offending.rb
      OUTPUT
      expect(todo).to eq(<<~YAML)
        #{header}
        # Offense count: 2
        Style/ClassVars:
          Exclude:
            - 'offending.rb'
      YAML
    end

    it 'leaves nothing for --report-unused-todo-entries to report' do
      cli.run(['--prune-todo'])
      $stdout.truncate(0)

      expect(RuboCop::CLI.new.run(['--report-unused-todo-entries', 'offending.rb'])).to eq(0)
      expect($stderr.string).not_to include('unused todo')
    end
  end

  context 'when every todo entry is still needed' do
    let(:source) do
      <<~YAML
        # Offense count: 2
        Style/ClassVars:
          Exclude:
            - 'offending.rb'
      YAML
    end

    before { create_file('.rubocop_todo.yml', source) }

    it 'does not change the todo file' do
      expect(cli.run(['--prune-todo'])).to eq(0)
      expect($stdout.string).to eq("No unused todo entries found in `.rubocop_todo.yml`.\n")
      expect(todo).to eq(source)
    end
  end

  context 'when a cop has other settings than `Exclude`' do
    before do
      create_file('.rubocop_todo.yml', <<~YAML)
        # Offense count: 1
        Style/ClassVars:
          Enabled: true
          Exclude:
            - 'clean.rb'
      YAML
    end

    it 'removes only the `Exclude` setting' do
      expect(cli.run(['--prune-todo'])).to eq(0)
      expect(todo).to eq(<<~YAML)
        # Offense count: 1
        Style/ClassVars:
          Enabled: true
      YAML
    end
  end

  context 'when the todo file lists a cop that is not loaded or a glob' do
    let(:source) do
      <<~YAML
        Unloaded/ExtensionCop:
          Exclude:
            - 'clean.rb'
        Style/ClassVars:
          Exclude:
            - '**/offending*.rb'
            - 'offending.rb'
      YAML
    end

    before { create_file('.rubocop_todo.yml', source) }

    it 'keeps the entries that cannot be judged' do
      expect(cli.run(['--prune-todo', '--ignore-unrecognized-cops'])).to eq(0)
      expect(todo).to eq(source)
    end
  end

  context 'when a listed file cannot be parsed' do
    let(:source) do
      <<~YAML
        Style/ClassVars:
          Exclude:
            - 'broken.rb'
            - 'offending.rb'
      YAML
    end

    before do
      create_file('broken.rb', <<~RUBY)
        # frozen_string_literal: true

        @@bad = (
      RUBY
      create_file('.rubocop_todo.yml', source)
    end

    it 'keeps the entries of the file' do
      expect(cli.run(['--prune-todo'])).to eq(0)
      expect(todo).to eq(source)
    end
  end

  context 'when the todo file is not laid out as generated' do
    let(:source) do
      <<~YAML
        Style/ClassVars:
          Exclude: ['clean.rb', 'offending.rb']
      YAML
    end

    before { create_file('.rubocop_todo.yml', source) }

    it 'does not change the todo file and lists the entries to remove' do
      expect(cli.run(['--prune-todo'])).to eq(2)
      expect($stderr.string).to include(
        'Could not prune `.rubocop_todo.yml` safely; remove 1 unused todo entry by hand:'
      )
      expect($stderr.string).to include('  Style/ClassVars: clean.rb')
      expect(todo).to eq(source)
    end
  end

  context 'when there is no todo file' do
    before { create_empty_file('.rubocop.yml') }

    it 'notes there is nothing to prune' do
      expect(cli.run(['--prune-todo'])).to eq(0)
      expect($stderr.string).to include('No `.rubocop_todo.yml` found; nothing to prune.')
    end
  end

  context 'when paths are given' do
    before { create_empty_file('.rubocop_todo.yml') }

    it 'fails' do
      expect(cli.run(['--prune-todo', 'clean.rb'])).to eq(2)
      expect($stderr.string).to include('--prune-todo does not accept paths.')
    end
  end
end
